'use strict';
(function(){
 const c={user:null,household:null,households:[],revision:0,status:null,dirty:false,sending:false,conflict:null,sequence:0,lastError:'',pendingKey:'',server:false,pushSubscribed:false,expired:false};
 const guest=()=>{try{return normalize(JSON.parse(localStorage.getItem('baraka-v1'))||seed())}catch{return normalize(seed())}};
 const pendingKey=()=>c.user&&c.household?'baraka-pending-'+c.user.id+'-'+c.household.id:'';
 async function request(path,method='GET',body){if(location.protocol==='file:')throw Error('Hisob uchun npm start orqali http://localhost:3000 manzilini oching.');let response;try{response=await fetch(path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(20000)})}catch{throw Error('Server bilan aloqa yo‘q. Server ishlayotganini tekshiring.')}let data;try{data=await response.json()}catch{throw Error('Server javobi noto‘g‘ri. npm start bilan serverni qayta ishga tushiring.')}if(!response.ok){const error=Error(data.error||'So‘rov bajarilmadi.');error.status=response.status;error.data=data;throw error}return data}
 function cacheOffline(data){try{localStorage.setItem('baraka-offline',JSON.stringify(data))}catch{}}
 function adopt(data){cacheOffline(data);document.body.classList.toggle('auth-pending',false);const preferences={theme:state.settings.theme,privacy:state.settings.privacy,motion:state.settings.motion};c.user=data.user;c.household=data.household;c.households=data.households;c.revision=data.revision;c.pendingKey=pendingKey();state=normalize(data.state);Object.assign(state.settings,preferences);c.dirty=false;c.conflict=null;c.lastError='';c.expired=false;c.sequence++;render();}
 function changed(){if(!c.user)return;c.dirty=true;c.sequence++;try{localStorage.setItem(pendingKey(),JSON.stringify({householdId:c.household.id,revision:c.revision,state}))}catch{}paint();queueMicrotask(()=>flush().catch(()=>{}));}
 async function flush(){if(!c.user||!c.dirty)return true;if(c.conflict)throw Error('Sinxronlash farqini avval hal qiling.');if(c.sending){await c.flight;if(c.dirty)return flush();return true}c.sending=true;
 c.flight=(async()=>{while(c.dirty&&!c.conflict){const version=c.sequence,householdId=c.household.id,payload=JSON.parse(JSON.stringify(state));try{const data=await request('/api/state','PUT',{state:payload,revision:c.revision,householdId});c.revision=data.revision;c.household=data.household;c.households=data.households;cacheOffline(data);if(version===c.sequence){const preferences={theme:state.settings.theme,privacy:state.settings.privacy,motion:state.settings.motion};state=normalize(data.state);Object.assign(state.settings,preferences);c.dirty=false;try{localStorage.removeItem(pendingKey())}catch{}}c.lastError='';}catch(error){c.lastError=error.message;if(error.status===401)c.expired=true;if(error.status===409&&error.data?.conflict)c.conflict=error.data;throw error}}})().finally(()=>{c.sending=false;paint()});return c.flight}
 async function poll(){if(!c.user||c.sending||c.conflict||c.expired)return;if(c.dirty){try{await flush()}catch{}return}const sequence=c.sequence;try{const data=await request('/api/state');if(c.dirty||c.sending||c.sequence!==sequence)return;if(data.user.id!==c.user.id||data.household.id!==c.household.id||data.revision!==c.revision)adopt(data);c.lastError='';paint()}catch(e){c.lastError=e.message;if(e.status===401)c.expired=true;paint()}}
 function paint(){const b=$('#account-button');if(!b)return;b.textContent=c.user?c.user.name:'Kirish';b.title=c.user?c.user.email:'Hisobga kirish';const banner=$('#cloud-banner');if(c.user){const problem=c.conflict?'Boshqa qurilmada ham o‘zgarish bor. Nusxalarni tekshiring.':(c.lastError?(c.dirty?'Telefonda saqlandi · Sinxronlash kutilmoqda. ':'')+c.lastError:'')|| (c.dirty?(navigator.onLine===false?'Telefonda saqlandi · Sinxronlash kutilmoqda':'Telefonda saqlandi · Serverga yuborilmoqda…'):'Serverga yuborildi');banner.innerHTML=`<div class="sync-banner ${c.conflict||c.lastError?'sync-warning':''}"><span class="status-dot"></span><span><b>${esc(c.household.name)}</b> · ${esc(problem)}</span><button class="text-button" onclick="${c.expired?"openAccount('login')":c.conflict?'openSyncConflict()':'retrySync()'}">${c.expired?'Qayta kirish':c.conflict?'Tekshirish':'Yangilash ↻'}</button></div>`}else banner.innerHTML='';document.querySelectorAll('.local-status').forEach(el=>{el.innerHTML=`<i class="status-dot"></i> ${c.user?'Server hisobi':'Qurilmada saqlanadi'}`})}
 function familyPanel(){if(!c.user)return `<div class="insight-banner"><div class="insight-icon">${icon('users')}</div><div><b>Oilangiz o‘z telefonidan qo‘shilsin</b><p>Avval hisob yarating. Oila egasi bir martalik taklif kodi beradi.</p></div><button class="primary" onclick="openAccount()">Hisobga kirish</button></div>`;return `<section class="card section-bottom"><div class="card-head"><div><h2>Serverdagi haqiqiy oila</h2><p>${esc(c.household.name)} · ${c.household.members.length} ta hisob</p></div><div class="settings-actions">${c.household.ownerId===c.user.id?'<button class="secondary" onclick="createFamilyInvite()">Taklif kodi</button>':''}<button class="primary" onclick="openFamilyJoin()">Oilaga qo‘shilish</button></div></div>${c.household.members.map(m=>`<div class="member"><span class="avatar">${esc(m.name[0])}</span><div class="member-text"><b>${esc(m.name)}</b><small>${m.role==='owner'?'Oila egasi':m.role==='child'?'Bola · shaxsiy vazifalar va xaridlar':'Umumiy budjetga kirish huquqi bor'}</small></div>${c.household.ownerId===c.user.id&&m.id!==c.user.id?`${m.role==='child'?`<button class="text-button" onclick="openAllowance('${m.id}')">Cho‘ntak puli</button>`:''}<button class="text-button" onclick="setFamilyRole('${m.id}','${m.role==='child'?'member':'child'}')">${m.role==='child'?'Katta a’zo qilish':'Bola ruxsati'}</button><button class="text-button" onclick="revokeFamilyMember('${m.id}')">Kirishni bekor qilish</button>`:'<span class="badge good">Faol</span>'}</div>`).join('')}<div class="form-note">Oila a’zolari umumiy budjetni tahrirlay oladi. Taklif kodini faqat ishonchli yaqinlaringizga bering. Quyidagi mahalliy a’zo nomlari alohida hisobga kirish huquqini bermaydi.</div></section>`}
 function accountPanel(){return `<section class="card section-bottom"><div class="card-head"><div><h2>${c.user?'Server hisobi':'Hisobga kirish va saqlash'}</h2><p>${c.user?esc(c.user.email):'Shaxsiy hisob va oilaviy sinxronlash'}</p></div>${c.user?'<button class="secondary" onclick="logoutAccount()">Chiqish</button>':'<button class="primary" onclick="openAccount()">Kirish / Ro‘yxatdan o‘tish</button>'}</div>${c.user?`<div class="settings-row"><div><h3>Parol xavfsizligi</h3><p>Parolni yangilaganda boshqa qurilmalardagi sessiyalar yopiladi.</p></div><button class="secondary" onclick="changeAccountPassword()">Parolni o‘zgartirish</button></div><div class="settings-row"><div><h3>Faol oila</h3><p>Har bir oila ma’lumotlari alohida. Oldingi hisobingiz saqlanadi.</p></div><select class="select-control" onchange="switchFamily(this.value)">${c.households.map(h=>`<option value="${h.id}" ${h.id===c.household.id?'selected':''}>${esc(h.name)}</option>`).join('')}</select></div><div class="settings-row"><div><h3>Qurilmadagi hisobni ko‘chirish</h3><p>Oldingi mahalliy yozuvlarni faol oiladagi hisob bilan almashtirishdan oldin tasdiq so‘raladi.</p></div><button class="secondary" onclick="importGuestAccount()">Ko‘chirish</button></div>`:`<p class="section-text">${c.server?'Hisoblar ushbu ishlayotgan serverda saqlanadi.':'Hisob uchun saytni npm start orqali oching.'} ${c.status?.cloud?'Server HTTPS manzilida ishlamoqda.':'Internetdagi bulutga joylashtirish hali bajarilmagan.'}</p>`}<div class="settings-row"><div><h3>Telefon eslatmalari</h3><p>${!c.status?.push?.ready?'Serverda PUSH_CONTACT sozlanishi kerak.':!c.user?'Avval hisobga kiring.':'Yaqin 3 kunlik to‘lovlar va qarzlar uchun kuniga bitta umumiy eslatma. Server ishlab turishi kerak.'} Qurilma ruxsati va HTTPS (yoki localhost) talab etiladi.</p></div><button class="secondary" ${c.status?.push?.ready&&c.user?'':'disabled'} onclick="${c.pushSubscribed?'disablePhonePush()':'enablePhonePush()'}">${c.pushSubscribed?'O‘chirish':'Yoqish'}</button></div>${c.pushSubscribed?'<button class="text-button" onclick="testPhonePush()">Sinov bildirishnomasi yuborish ↗</button>':''}</section>`}
 async function submit(d,type){const button=$('#save-button');if(button.disabled)return;button.disabled=true;try{if(type==='auth-password'){if(d.password!==d.passwordConfirm)throw Error('Parollar bir xil emas.');await request('/api/auth/password','POST',{currentPassword:d.currentPassword,password:d.password});closeModal();toast('Parol yangilandi. Boshqa sessiyalar yopildi.')}else if(type==='auth-register'||type==='auth-login'){if(type==='auth-register'&&d.password!==d.passwordConfirm)throw Error('Parollar bir xil emas.');const data=await request(type==='auth-register'?'/api/auth/register':'/api/auth/login','POST',{email:d.email,password:d.password,...(type==='auth-register'?{name:d.name}:{})});closeModal();adopt(data);try{localStorage.setItem('baraka-auth-event',JSON.stringify({action:'login',nonce:uid()}))}catch{}await recoverPending();toast('Hisobga kirdingiz ✓')}else if(type==='family-allowance'){await flush();const data=await request('/api/family/allowance','POST',{userId:d.userId,amount:d.amount,walletId:d.walletId,key:d.key});closeModal();adopt(data);toast('Cho‘ntak puli qayd etildi')}else if(type==='family-join'){await flush();const data=await request('/api/family/join','POST',{code:d.code});closeModal();adopt(data);toast('Oilaviy hisobga qo‘shildingiz ✓')}}catch(error){$('#form-error').textContent=error.message}finally{button.disabled=false}}
 async function recoverPending(){let saved;try{saved=JSON.parse(localStorage.getItem(pendingKey()))}catch{}if(saved?.state){const recovered=normalize(saved.state);confirmAction('Yuborilmagan o‘zgarishlar bor','<p class="section-text">Bu hisob uchun oldin serverga yuborilmagan mahalliy nusxa topildi. Uni yuklasangiz, serverdagi yangi o‘zgarishlar bilan farq bo‘lishi mumkin. Avval zaxira nusxa olib solishtiring.</p>',()=>{const currentServer={state,revision:c.revision,user:c.user,household:c.household,households:c.households};state=recovered;c.dirty=true;c.sequence++;c.conflict=currentServer;render();openSyncConflict()},'Mahalliy nusxani ko‘rish')}}
 async function payUtility(id,d){try{if(!c.user)throw Error('Avval hisobga kiring.');await flush();const key=uid();const result=await request('/api/utilities/pay','POST',{accountId:id,walletId:d.walletId,amount:d.amount,idempotencyKey:key});closeModal();setModal('Operator sahifasida tasdiqlang',`<p class="section-text">To‘lov hali tasdiqlanmagan. Rasmiy to‘lov sahifasiga o‘ting. Qaytgandan so‘ng holatni yangilang.</p>${result.checkoutUrl?`<a class="primary" href="${esc(result.checkoutUrl)}" target="_blank" rel="noopener noreferrer">Operator sahifasini ochish ↗</a>`:'<p class="section-text">Operator javobini tekshiring.</p>'}`,false);loadUtilityPayments()}catch(e){$('#form-error').textContent=e.message}}
 globalThis.barakaCloud=Object.assign(c,{request,changed,paint,familyPanel,accountPanel,submit,payUtility,flush});
 globalThis.openAccount=function(mode='login'){if(c.user&&!c.expired){location.hash='settings';return}if(location.protocol==='file:'){toast('Hisob uchun npm start va http://localhost:3000 manzilidan foydalaning.');return}formType=mode==='register'?'auth-register':'auth-login';setModal(mode==='register'?'Baraka hisobini yaratish':'Hisobingizga xush kelibsiz',`${mode==='register'?nameField('Ismingiz','',40):''}${field('Email','email','email','','required maxlength="200" autocomplete="username"')}${field('Parol','password','password','','required maxlength="128" autocomplete="'+(mode==='register'?'new-password':'current-password')+'"')}${mode==='register'?field('Parolni takrorlang','passwordConfirm','password','','required maxlength="128" autocomplete="new-password"'):''}<p class="section-text">${mode==='register'?'Hisobingiz bormi?':'Yangi foydalanuvchimisiz?'} <button type="button" class="text-button" onclick="openAccount('${mode==='register'?'login':'register'}')">${mode==='register'?'Kirish':'Hisob yaratish'}</button></p><div class="form-note">${c.status?.cloud?'Ma’lumotlar sayt serverida saqlanadi.':'Hozirgi server mahalliy kompyuteringizda. Bulut uchun HTTPS hosting kerak.'} Parolni o‘zingiz tanlang. Parol bo‘sh bo‘lmasin va 128 belgidan oshmasin.</div>`);$('#save-button').textContent=mode==='register'?'Hisob yaratish':'Kirish'};
 globalThis.changeAccountPassword=function(){formType='auth-password';setModal('Parolni yangilash',field('Hozirgi parol','currentPassword','password','','required maxlength="128" autocomplete="current-password"')+field('Yangi parol','password','password','','required maxlength="128" autocomplete="new-password"')+field('Yangi parolni takrorlang','passwordConfirm','password','','required maxlength="128" autocomplete="new-password"'))};
 globalThis.openAllowance=function(userId){formType='family-allowance';setModal('Cho‘ntak pulini qayd etish',field('A’zo','userId','hidden',userId)+field('So‘rov','key','hidden',uid())+amountField('Summa (so‘m)','amount')+select('Qaysi hamyondan','walletId',state.wallets.map(w=>[w.id,w.name]))+'<p>Oilaviy hamyonda xarajat va bolaning shaxsiy hisobida kirim yaratiladi. Haqiqiy bank o‘tkazmasi bajarilmaydi.</p>')};
 globalThis.setFamilyRole=function(userId,role){confirmAction('A’zo ruxsati o‘zgartirilsinmi?','<p>Bola faqat o‘z vazifalari, xarid ro‘yxati va shaxsiy hisobini ko‘radi.</p>',async()=>{try{await flush();adopt(await request('/api/family/role','POST',{userId,role}))}catch(e){toast(e.message)}})};
 globalThis.openFamilyJoin=function(){if(!c.user){openAccount();return}formType='family-join';setModal('Oilangizga qo‘shiling',field('Bir martalik taklif kodi','code','text','','required maxlength="100" autocomplete="off"')+'<p class="section-text">Oila egasidan kod oling. Shaxsiy hisobingiz saqlanadi va Sozlamalardan oilalar orasida almashishingiz mumkin.</p>')};
 globalThis.createFamilyInvite=async function(){try{await flush();const result=await request('/api/family/invite','POST',{});setModal('Oilangiz uchun taklif kodi',`<p class="section-text">Kod bir marta ishlaydi va 24 soatdan keyin eskiradi. A’zo o‘z hisobiga kirib, “Oilaga qo‘shilish” bo‘limiga kodni kiritsin.</p><label class="field">Taklif kodi<input id="invite-code" readonly value="${esc(result.code)}" onclick="this.select()"></label><label class="field">Taklif havolasi<input readonly value="${esc(location.origin+'/?invite='+encodeURIComponent(result.code))}" onclick="this.select()"></label><button type="button" class="secondary" onclick="copyInviteCode()">Kodni nusxalash</button>`,false)}catch(e){toast(e.message)}};
 globalThis.copyInviteCode=async function(){const el=$('#invite-code');try{await navigator.clipboard.writeText(el.value);toast('Taklif kodi nusxalandi')}catch{el.select();toast('Belgilangan kodni Ctrl+C bilan nusxalang.')}};
 globalThis.retrySync=async function(){try{await flush();await poll();if(!c.lastError)toast('Server holati yangilandi')}catch(e){toast(e.message)}};
 globalThis.openSyncConflict=function(){if(!c.conflict)return;setModal('Ikki nusxada o‘zgarish bor','<p class="section-text">Sizning o‘zgarishlaringiz qurilmada saqlangan. Boshqa a’zo ham hisobni o‘zgartirgan. Avval mahalliy nusxani yuklab oling, keyin qaysi nusxa qolishini tanlang.</p><div class="conflict-actions"><button type="button" class="secondary" onclick="exportBackup()">Mahalliy nusxani yuklab olish</button><button type="button" class="secondary" onclick="useServerSnapshot()">Serverdagi nusxani olish</button><button type="button" class="danger-button" onclick="replaceServerSnapshot()">Mening nusxam bilan almashtirish</button></div>',false)};
 globalThis.useServerSnapshot=function(){const data=c.conflict;if(!data)return;confirmAction('Server nusxasini olasizmi?','<p class="section-text">Yuborilmagan tahrirlaringiz faol hisobdan chiqariladi. Avval ularni faylga yuklab oling.</p>',()=>{try{localStorage.removeItem(pendingKey())}catch{}adopt(data);toast('Server nusxasi olindi')})};
 globalThis.replaceServerSnapshot=function(){if(!c.conflict)return;confirmAction('Umumiy hisob almashtirilsinmi?','<p class="section-text">Boshqa a’zoning yangi tahrirlari sizning nusxangiz bilan almashtiriladi. U bilan kelishib oling.</p>',async()=>{c.revision=c.conflict.revision;c.conflict=null;c.dirty=true;try{await flush();render();toast('Nusxa saqlandi')}catch(e){toast(e.message)}})};
 globalThis.switchFamily=async function(id){try{await flush();const data=await request('/api/family/switch','POST',{id});adopt(data);await recoverPending()}catch(e){toast(e.message);render()}};
 globalThis.revokeFamilyMember=function(userId){confirmAction('A’zoning kirishi bekor qilinsinmi?','<p class="section-text">U bu oilaning ma’lumotlarini ko‘ra va tahrirlay olmaydi. Avvalgi amaliyotlar saqlanadi.</p>',async()=>{try{await flush();await request('/api/family/remove','POST',{userId});await poll();render()}catch(e){toast(e.message)}})};
 globalThis.importGuestAccount=function(){if(!c.user)return;const old=guest();confirmAction('Qurilmadagi nusxani ko‘chirasizmi?',`<p class="section-text">Qurilmada ${old.transactions.length} ta amaliyot bor${old.demo?' — ular namunaviy yozuvlar':''}. Faol oiladagi yozuvlar ular bilan almashtiriladi. Avval ikkala nusxani zaxiralang.</p>`,()=>{state=old;state.demo=false;changed();render()})};
 globalThis.logoutAccount=async function(){try{if(!c.expired){try{await flush()}catch(error){if(error.status!==401)throw error}if(!c.expired)await disablePhonePush(true)}try{await request('/api/auth/logout','POST',{})}catch(error){if(error.status!==401)throw error}try{localStorage.setItem('baraka-auth-event',JSON.stringify({action:'logout',nonce:uid()}))}catch{}try{localStorage.removeItem('baraka-offline')}catch{}c.user=null;c.household=null;c.households=[];c.dirty=false;c.conflict=null;c.lastError='';state=guest();render();toast('Hisobdan chiqdingiz');if(typeof location.replace==='function')location.replace('/')}catch(e){toast('Chiqish bajarilmadi: '+e.message)}};
 function urlBytes(str){const base=str.replace(/-/g,'+').replace(/_/g,'/'),decoded=atob(base);return Uint8Array.from(decoded,c=>c.charCodeAt(0))}
 globalThis.enablePhonePush=async function(){try{if(!c.user)throw Error('Avval hisobga kiring.');if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window)||!window.isSecureContext)throw Error('Brauzer push eslatmalarini qo‘llamaydi yoki HTTPS yo‘q.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Bildirishnomaga ruxsat berilmadi.');const reg=await navigator.serviceWorker.register('/sw.js');await navigator.serviceWorker.ready;const sub=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBytes(c.status.push.publicKey)});await request('/api/push/subscribe','POST',sub.toJSON());c.pushSubscribed=true;render();toast('Telefon eslatmalari yoqildi ✓')}catch(e){toast(e.message)}};
 globalThis.disablePhonePush=async function(silent=false){try{if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.getRegistration('/sw.js'),sub=await reg?.pushManager.getSubscription();if(sub){await request('/api/push/unsubscribe','POST',{endpoint:sub.endpoint});await sub.unsubscribe()}}c.pushSubscribed=false;if(!silent){render();toast('Eslatmalar o‘chirildi')}}catch(e){if(!silent)toast(e.message)}};
 globalThis.testPhonePush=async function(){try{await request('/api/push/test','POST',{});toast('Push xizmatiga yuborildi. Qurilmada tekshiring.')}catch(e){toast(e.message)}};
 async function boot(){if(location.protocol==='file:'){paint();return}try{c.status=await request('/api/status');c.server=true;try{const data=await request('/api/auth/me');adopt(data);await recoverPending();const invite=sessionStorage.getItem('baraka-invite');if(invite){openFamilyJoin();$('#fields [name=code]').value=invite;sessionStorage.removeItem('baraka-invite')}if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.getRegistration('/sw.js');c.pushSubscribed=!!(await reg?.pushManager.getSubscription())}}catch(e){if(e.status!==401)c.lastError=e.message;else if(typeof location.replace==='function'){location.replace('/');return}}render();if(!c.user){const message=document.querySelector('.session-message');if(message)message.textContent=c.lastError||'Hisobga kirish sahifasiga qayting.'}}catch(e){c.lastError=e.message;try{const cached=JSON.parse(localStorage.getItem('baraka-offline'));if(cached?.user&&cached?.state){adopt(cached);const saved=JSON.parse(localStorage.getItem(pendingKey())||'null');if(saved?.state){state=normalize(saved.state);c.dirty=true;c.sequence++}c.lastError='Internet yo‘q · Qurilmadagi nusxa ochildi';render()}}catch{}paint();const message=document.querySelector('.session-message');if(message)message.textContent=e.message}}
 let lastAutoPoll=0;
 setInterval(()=>{if(!document.hidden&&Date.now()-lastAutoPoll>=(c.status?.syncPollMs||10000)){lastAutoPoll=Date.now();poll()}},10000);
 addEventListener('storage',e=>{if(e.key==='baraka-auth-event'&&e.newValue){let message;try{message=JSON.parse(e.newValue)}catch{return}if(message.action==='logout'){try{localStorage.removeItem('baraka-offline')}catch{}c.user=null;c.household=null;c.dirty=false;c.conflict=null;state=guest();render();if(typeof location.replace==='function')location.replace('/')}else if(c.user){c.expired=true;c.lastError='Boshqa oynada hisob o‘zgardi. Qayta kiring.';paint()}}});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll()});
 addEventListener('beforeunload',e=>{if(c.dirty){e.preventDefault();e.returnValue=''}});
 addEventListener('online',()=>poll());
 if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('/sw.js').catch(()=>{});
 boot();
})();
